/**
 * Keys arrive in three spellings — kebab from the picker, PascalCase from
 * enrichment, lowercase from the chat card — so compare on letters and digits
 * only. A miss draws the question mark rather than crashing the grid.
 */
const canonical = (value: string) =>
  value.toLowerCase().replace(/[^a-z0-9]/g, "");

const BY_CANONICAL = new Map(
  Object.entries(SERVICE_ICON_COMPONENTS).map(([key, icon]) => [
    canonical(key),
    icon,
  ]),
);

export function getServiceIcon(name?: string): LucideIcon {
  if (!name) return HelpCircle;
  return BY_CANONICAL.get(canonical(name.trim())) ?? HelpCircle;
}
